import { appearanceFact, bodyAppearance } from "./bodyAppearance";
import type { CelestialObject, ObjectId } from "../types/celestial";
import generated from "./generated/solarSystemBodies.json";

/**
 * Bodies generated by scripts/prepare-solar-system-bodies.py from JPL SSD satellite
 * tables and Horizons. Orbits are fitted elements validated on held-out epochs; see
 * EPHEMERIS.md. Physical values are published measurements or explicitly unmeasured.
 */
export interface GeneratedOrbit {
  id: ObjectId;
  parentId: ObjectId;
  /** Elements in the JPL reference plane at `epochTdbMs`: km, degrees, degrees/day. */
  elements: { a: number; e: number; i: number; node: number; peri: number; M: number; nM: number; nNode: number; nPeri: number };
  /** Rows map reference-plane coordinates to ecliptic J2000. */
  frameToEcliptic: number[][];
  referencePlane: string;
  holdoutErrorDeg: number;
  /** Adds factor × (companion relative to parent), e.g. Pluto–Charon barycenter offsets. */
  companionOffset?: { id: ObjectId; factor: number };
  horizonsId: string;
}

interface GeneratedRecord extends GeneratedOrbit {
  name: string;
  kind: "satellite" | "small-body";
  category: string;
  radiusKm: number | null;
  radiusSource: string | null;
  gmKm3s2: number | null;
}

const data = generated as unknown as { epochTdb: string; generated: string; bodies: GeneratedRecord[] };
export const GENERATED_EPOCH_TDB_MS = Date.parse(data.epochTdb);
export const GENERATED_ON = data.generated;

/**
 * Published sizes where the Horizons header has none (volume-equivalent mean radius, km).
 * Pluto: Nimmo et al. 2017 (New Horizons). Eris: Sicardy et al. 2011 (occultation).
 * Haumea: Ortiz et al. 2017 (occultation ellipsoid). Makemake: Ortiz et al. 2012.
 * Gonggong: Kiss et al. 2019. Quaoar: Braga-Ribas et al. 2013. Orcus: Fornasier et al. 2013.
 * Sedna: Pál et al. 2012 (thermal). Arrokoth: Spencer et al. 2020. Braille: Deep Space 1.
 */
const PUBLISHED_RADII: Record<string, [number, string]> = {
  pluto: [1188.3, "Nimmo et al. 2017, New Horizons"],
  eris: [1163, "Sicardy et al. 2011, stellar occultation"],
  haumea: [798, "Ortiz et al. 2017, occultation (triaxial; volume-equivalent)"],
  makemake: [715, "Ortiz et al. 2012, stellar occultation"],
  gonggong: [615, "Kiss et al. 2019, thermal + Kepler photometry"],
  quaoar: [555, "Braga-Ribas et al. 2013, stellar occultation"],
  orcus: [458, "Fornasier et al. 2013, Herschel thermal"],
  sedna: [497, "Pál et al. 2012, Herschel thermal"],
  arrokoth: [9, "Spencer et al. 2020, New Horizons (volume-equivalent)"],
  braille: [0.8, "Deep Space 1 imaging (approx. 2.1 × 1 × 1 km)"],
};

/** Shown size for bodies with no published radius. Never used as a measurement. */
export const PLACEHOLDER_RADIUS_KM = 2;
const G_KM3_PER_KG_S2 = 6.6743e-20;

export const generatedOrbits = new Map<ObjectId, GeneratedOrbit>(
  data.bodies.map((body) => [body.id, body]),
);

/** "S2017_J_2" → "S/2017 J 2" (IAU provisional designation format). */
export function displayName(name: string): string {
  const match = /^S(\d{4})_([A-Z])_?(\d+)$/.exec(name);
  return match ? `S/${match[1]} ${match[2]} ${match[3]}` : name;
}

function periodDays(orbit: GeneratedOrbit): number {
  const { nM, nNode, nPeri } = orbit.elements;
  return 360 / Math.abs(nM + nNode + nPeri);
}

function describe(record: GeneratedRecord, parentName: string): string {
  const { a, e, i } = record.elements;
  const retrograde = i > 90;
  if (record.kind === "small-body")
    return `${record.category}. Mean distance ${(a / 149_597_870.7).toFixed(2)} AU, eccentricity ${e.toFixed(3)}, orbital period ${(periodDays(record) / 365.25).toFixed(1)} years.`;
  const regular = record.referencePlane !== "ecliptic";
  return `${regular ? "Regular" : "Irregular"}${retrograde ? ", retrograde" : ""} moon of ${parentName}. Mean distance ${Math.round(a).toLocaleString("en-US")} km; one orbit takes ${periodDays(record).toFixed(periodDays(record) < 10 ? 2 : 0)} days.`;
}

/**
 * Catalog entries for generated bodies that are not already hand-curated.
 * `parents` supplies display scales for the compressed Overview layout.
 */
export function generatedCelestialObjects(
  existing: ReadonlySet<ObjectId>,
  parents: ReadonlyMap<ObjectId, CelestialObject>,
): CelestialObject[] {
  const created = new Map<ObjectId, CelestialObject>();
  // Parents (e.g. Pluto) must exist before their moons are scaled.
  const ordered = [...data.bodies].sort((a, b) => Number(a.parentId !== "sun") - Number(b.parentId !== "sun"));
  for (const record of ordered) {
    if (existing.has(record.id)) continue;
    const parent = parents.get(record.parentId) ?? created.get(record.parentId);
    if (!parent) continue;
    const published = PUBLISHED_RADII[record.id];
    const radiusKm = record.radiusKm ?? published?.[0] ?? null;
    const radiusSource = record.radiusKm ? record.radiusSource : published?.[1] ?? null;
    const gm = record.gmKm3s2 && record.gmKm3s2 > 0 ? record.gmKm3s2 : null;
    const unmeasured: NonNullable<CelestialObject["unmeasured"]> = [];
    if (radiusKm === null) unmeasured.push("radius");
    if (gm === null) unmeasured.push("mass");
    const regular = record.kind === "satellite" && record.referencePlane !== "ecliptic";
    if (!regular) unmeasured.push("rotation");
    const shownRadius = radiusKm ?? PLACEHOLDER_RADIUS_KM;
    const period = periodDays(record);
    const name = displayName(record.name);
    created.set(record.id, {
      id: record.id,
      name,
      category: record.kind === "satellite" ? "Natural satellite" : record.category,
      parentId: record.parentId,
      description: describe(record, parent.name),
      radiusKm: shownRadius,
      massKg: gm ? gm / G_KM3_PER_KG_S2 : 0,
      gravityMs2: gm ? (gm * 1000) / shownRadius ** 2 : 0,
      orbitalPeriodDays: period,
      // Regular moons are assumed tidally locked; other spins are unmeasured here.
      rotationPeriodHours: regular ? period * 24 : 0,
      semiMajorAxisKm: record.elements.a,
      axialTiltDeg: 0,
      color: record.category.includes("comet") ? "#5d5852" : "#8e8a85",
      source: record.kind === "satellite"
        ? { label: "JPL SSD planetary satellites + Horizons", url: "https://ssd.jpl.nasa.gov/sats/elem/" }
        : { label: "JPL Horizons / Small-Body Database", url: `https://ssd.jpl.nasa.gov/tools/sbdb_lookup.html#/?sstr=${encodeURIComponent(record.horizonsId.replace(/^DES=|;.*$/g, ""))}` },
      display: {
        radius: Math.max(0.03, Math.min(0.3, 0.03 + Math.log10(1 + shownRadius) * 0.06)),
        orbitRadius: overviewOrbitRadius(record, parent),
        initialPhase: 0,
        inclination: record.referencePlane === "ecliptic" ? Math.min(record.elements.i, 180 - record.elements.i) * Math.PI / 180 : 0,
      },
      facts: [
        { label: "Size", value: radiusKm === null ? `Not measured; shown at a nominal ${PLACEHOLDER_RADIUS_KM} km radius` : `${radiusKm.toLocaleString("en-US")} km mean radius (${radiusSource})` },
        { label: "Mass", value: gm ? "Derived from JPL GM" : "Not measured" },
        { label: "Orbit model", value: `JPL ${record.kind === "satellite" ? "satellite" : "small-body"} orbit fitted to Horizons (${record.referencePlane} plane); held-out error ${record.holdoutErrorDeg.toFixed(2)}°` },
        { label: "Appearance", value: appearanceFact(bodyAppearance(
          { id: record.id, parentId: record.parentId, category: record.kind === "satellite" ? "Natural satellite" : record.category },
          { irregularOrbit: record.kind === "satellite" && record.referencePlane === "ecliptic" })) },
      ],
      ...(unmeasured.length ? { unmeasured } : {}),
    });
  }
  return [...created.values()];
}

/** [log10(a / AU), Overview ring radius] of the hand-tuned planets, Mercury → Neptune. */
const PLANET_RINGS: readonly [number, number][] = [
  [0.387, 10], [0.723, 14], [1, 19], [1.524, 25], [5.203, 37], [9.537, 49], [19.19, 61], [30.07, 73],
].map(([au, ring]) => [Math.log10(au), ring] as [number, number]);

/** Overview compresses distances logarithmically; these are display units only. */
function overviewOrbitRadius(record: GeneratedRecord, parent: CelestialObject): number {
  if (record.parentId === "sun") return compressedSolarDistance(record.elements.a);
  const ratio = Math.max(1.05, record.elements.a / Math.max(1, parent.radiusKm));
  return parent.display.radius * 1.2 + 1.6 * Math.log10(ratio);
}

/**
 * Overview display radius for a heliocentric distance: interpolates the hand-tuned
 * planet rings in log(distance) and extrapolates past Neptune. Display units only.
 */
export function compressedSolarDistance(distanceKm: number): number {
  {
    const x = Math.log10(Math.max(0.2, distanceKm / 149_597_870.7));
    const rings = PLANET_RINGS;
    if (x <= rings[0][0]) return rings[0][1] * (x / rings[0][0]) ** 0.5;
    for (let k = 1; k < rings.length; k++) {
      if (x <= rings[k][0]) {
        const [x0, y0] = rings[k - 1], [x1, y1] = rings[k];
        return y0 + ((x - x0) / (x1 - x0)) * (y1 - y0);
      }
    }
    const [xa, ya] = rings[rings.length - 2], [xb, yb] = rings[rings.length - 1];
    return Math.min(140, yb + ((x - xb) / (xb - xa)) * (yb - ya));
  }
}

/** Generated Sun-orbiting bodies show their true orbit shape in Overview. */
export function usesTrueOverviewShape(id: ObjectId): boolean {
  return generatedOrbits.get(id)?.parentId === "sun";
}
